class Solution {
    int K;
    string s;
    int memo[11][21][21][2][2];

    int dp(int pos, int diff, int mod, int tight, int started) {
        if (pos == (int)s.size())
            return (started && diff == 10 && mod == 0) ? 1 : 0;
        int &m = memo[pos][diff][mod][tight][started];
        if (!tight && m != -1) return m;
        int hi = tight ? s[pos] - '0' : 9;
        int res = 0;
        for (int d = 0; d <= hi; d++) {
            int nd = diff, nm = mod, ns = started;
            if (started || d > 0) {
                nd += (d % 2 == 0) ? 1 : -1;
                nm = (nm * 10 + d) % K;
                ns = 1;
            }
            res += dp(pos + 1, nd, nm, tight && (d == hi), ns);
        }
        if (!tight) m = res;
        return res;
    }

    int f(int n) {
        s = to_string(n);
        memset(memo, -1, sizeof(memo));
        return dp(0, 10, 0, 1, 0);
    }

public:
    int numberOfBeautifulIntegers(int low, int high, int k) {
        K = k;
        return f(high) - f(low - 1);
    }
};
